document.documentElement.classList.add('js');
const observer=new IntersectionObserver(items=>items.forEach(item=>{if(item.isIntersecting){item.target.classList.add('visible');observer.unobserve(item.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#navigation');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open);menu.classList.toggle('is-open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.classList.remove('is-open')}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.classList.remove('is-open')}});
let pending=false;function updateScroll(){const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.reading-progress').style.width=(max>0?scrollY/max*100:0)+'%';pending=false}addEventListener('scroll',()=>{if(!pending){requestAnimationFrame(updateScroll);pending=true}},{passive:true});updateScroll();
const chapters=new IntersectionObserver(items=>items.forEach(item=>{if(item.isIntersecting)nav.querySelectorAll('a').forEach(a=>a.classList.toggle('active',a.hash==='#'+item.target.id))}),{rootMargin:'-20% 0px -60% 0px'});['story','ritual','moments','identity'].forEach(id=>chapters.observe(document.getElementById(id)));
function setActive(buttons,current){buttons.forEach(b=>{const on=b===current;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on))})}
const steps=['ثبّت الحلقة الدائرية على حافة الكوب، بحيث يكون ورق الترشيح داخل الفتحة.','صُبّ الماء بهدوء على البُنّ في منتصف الفلتر، واترك القهوة تتقطّر إلى الكوب.','ارفع الفلتر بعد انتهاء التقطير. رشفة على مهلك، واللحظة صارت لك.'];const stepButtons=[...document.querySelectorAll('[data-step]')];stepButtons.forEach(b=>b.addEventListener('click',()=>{const n=Number(b.dataset.step);setActive(stepButtons,b);document.querySelector('#step-copy').textContent=steps[n];document.querySelector('.step-num').textContent='0'+(n+1)+' / 03';document.querySelector('.ritual-visual').dataset.manual='true';document.querySelector('.ritual-visual').style.setProperty('--product-zoom',[1.35,1.18,1][n]);document.querySelector('.ritual-visual').style.setProperty('--product-position',['65% 15%','50% 40%','40% 50%'][n])}));
const moments=[['بريك صغير. سوالف كثيرة.','دفاتر، ضحكة من القلب، ورشفة بين محاضرتين. أحيانًا أجمل جزء من اليوم هو الوقت اللي نقضيه مع بعض.'],['وقفة لك، وسط يومك.','بين اجتماع وتسليم، خذ لك لحظة ترتّب فيها أفكارك. قهوتك قريبة، وباقي اليوم نكمله على رواق.'],['كل مشوار له رشفة.','في شنطة سفرك، على طريق جديد، أو قبل موعد الإقلاع. خذ معك شيء تحبّه، واترك للحظة فرصة تفاجئك.'],['طلعة تحلى باللّمّة.','في الشاليه، حول طاولة الأصدقاء، أو في طلعة بلا خطة. قهوة، ناس نحبّهم، ووقت ننسى نحسبه.']];const momentButtons=[...document.querySelectorAll('[data-moment]')];momentButtons.forEach(b=>b.addEventListener('click',()=>{const n=Number(b.dataset.moment);setActive(momentButtons,b);document.querySelector('#moment-title').textContent=moments[n][0];document.querySelector('#moment-copy').textContent=moments[n][1];document.querySelector('#moment-number').textContent='0'+(n+1)+' / 04';const photo=document.querySelector('#moment-photo');photo.src='assets/'+['college','work','travel','weekend'][n]+'.webp';photo.alt=['لحظة الجامعة مع الصديقات','رومو خلال يوم العمل','قهوة رومو في السفر','رومو في الويكند مع الأصدقاء'][n];document.querySelector('.image-note').textContent=moments[n][0]}));
const weights=[...document.querySelectorAll('[data-weight]')];weights.forEach(b=>b.addEventListener('click',()=>{setActive(weights,b);document.querySelector('#type-sample').style.fontWeight=b.dataset.weight}));const colorData={"blue": {"hex": "#A0BEDA", "name": "BLUEBERRY", "title": "أزرق البلوبيري.", "copy": "مستوحى من الطبقة الزرقاء الناعمة على حبات البلوبيري، لون يحمل الانتعاش والهدوء.", "photo": "blueberry", "alt": "حبات البلوبيري، مرجع اللون الأزرق في هوية رومو"}, "cream": {"hex": "#F4E8D4", "name": "SAND DUNES", "title": "دفء الكثبان.", "copy": "كريمي مستوحى من الكثبان الرملية، نعومة طبيعية ودفء يرافق لحظتك.", "photo": "sand", "alt": "الكثبان الرملية، مرجع اللون الكريمي في هوية رومو"}, "brown": {"hex": "#34211B", "name": "CHOCOLATE", "title": "عمق الشوكولاتة.", "copy": "بني مستوحى من الشوكولاتة، لون غني يمنح الهوية عمقها ودفئها.", "photo": "chocolate", "alt": "قطع الشوكولاتة، مرجع اللون البني في هوية رومو"}};
let currentColor='blue';const colorButtons=[...document.querySelectorAll('[data-color]')];colorButtons.forEach(b=>b.addEventListener('click',()=>{currentColor=b.dataset.color;const c=colorData[currentColor];setActive(colorButtons,b);const panel=document.querySelector('#color-info');panel.style.background=c.hex;panel.style.color=currentColor==='brown'?'#F4E8D4':'#34211B';panel.classList.toggle('dark',currentColor==='brown');document.querySelector('#color-english').textContent=c.name;document.querySelector('#color-title').textContent=c.title;document.querySelector('#color-meaning').textContent=c.copy;document.querySelector('#color-code').textContent=c.hex;const photo=document.querySelector('#color-photo');photo.src='assets/'+c.photo+'.webp';photo.alt=c.alt;document.querySelector('#copy-color').lastElementChild.textContent='نسخ الكود'}));
document.querySelector('#copy-color').addEventListener('click',async()=>{const b=document.querySelector('#copy-color');try{await navigator.clipboard.writeText(colorData[currentColor].hex);b.lastElementChild.textContent='تم النسخ'}catch{b.lastElementChild.textContent='حدّد الكود لنسخه'}});
document.querySelector('#pattern-range').addEventListener('input',e=>{document.querySelector('.pattern-compare').dataset.manual='true';document.querySelector('.pattern-compare').style.setProperty('--split',e.target.value+'%')});
const filterButtons=[...document.querySelectorAll('[data-filter]')];filterButtons.forEach(b=>b.addEventListener('click',()=>{setActive(filterButtons,b);document.querySelectorAll('[data-category]').forEach(card=>{card.hidden=b.dataset.filter!=='all'&&card.dataset.category!==b.dataset.filter})}));
const cinema=document.querySelector('.cinema'),stage=document.querySelector('.cinema-sticky'),heroPhoto=document.querySelector('.hero-photo'),reduced=matchMedia('(prefers-reduced-motion: reduce)');const clamp=(n,min,max)=>Math.max(min,Math.min(n,max));let scrollFrame=0;function paintStory(){scrollFrame=0;if(reduced.matches)return;const top=cinema.getBoundingClientRect().top;const progress=clamp((84-top)/(cinema.offsetHeight-innerHeight),0,1);stage.style.setProperty('--cinema-scale',.72+clamp(progress*1.7,0,1)*.28);stage.style.setProperty('--cinema-copy',clamp((progress-.38)*3,0,1));stage.style.setProperty('--cinema-shade',clamp((progress-.35)*2,0,.9));paintChapters();heroPhoto.style.transform='scale('+(1+clamp(scrollY/innerHeight,0,1)*.08)+')'}function queueStory(){if(!scrollFrame)scrollFrame=requestAnimationFrame(paintStory)}addEventListener('scroll',queueStory,{passive:true});addEventListener('resize',queueStory);reduced.addEventListener('change',()=>{if(reduced.matches){stage.style.removeProperty('--cinema-scale');heroPhoto.style.transform='none'}else queueStory()});

function paintChapters(){
 const vh=innerHeight;
 const ritual=document.querySelector('.ritual-scroll');
 const r=ritual.getBoundingClientRect();
 const rp=clamp((100-r.top)/Math.max(1,ritual.offsetHeight-vh*.78),0,1);
 const visual=document.querySelector('.ritual-visual');
 if(!visual.dataset.manual){visual.style.setProperty('--product-zoom',1.17-rp*.17);visual.style.setProperty('--product-position','55% '+(30+rp*20)+'%')}
 const scene=document.querySelector('.business-scroll'),br=scene.getBoundingClientRect();
 const bp=clamp((100-br.top)/Math.max(1,scene.offsetHeight-vh*.72),0,1);
 scene.style.setProperty('--business-inset',(1-bp)*9+'%');
 scene.style.setProperty('--business-scale',1.12-bp*.12);
 scene.style.setProperty('--business-caption',clamp((bp-.2)*2,0,1));
 const compare=document.querySelector('.pattern-compare');
 if(!compare.dataset.manual){const p=clamp((vh*.85-compare.getBoundingClientRect().top)/(vh*.65),0,1);const v=Math.round(85-p*65);compare.style.setProperty('--split',v+'%');document.querySelector('#pattern-range').value=v}
 const footer=document.querySelector('footer');const fp=clamp((vh-footer.getBoundingClientRect().top)/vh,0,1);footer.style.setProperty('--footer-scale',.85+fp*.15);
}
paintStory();
